def game_score(points: str) -> str:
    labels = ["0", "15", "30", "40"]
    a = 0
    b = 0
    for p in points:
        if p == "A":
            a += 1
        elif p == "B":
            b += 1
        else:
            continue
        if a >= 4 and a - b >= 2:
            return "Game A"
        if b >= 4 and b - a >= 2:
            return "Game B"
    if a >= 3 and b >= 3:
        if a == b:
            return "40-40"
        return "Game A" if a - b >= 2 else "Game B"
    return f"{labels[min(a, 3)]}-{labels[min(b, 3)]}"
